    f.write(f"""# Transform for {task_id}
# Rule: Divide grid by separator rows/cols into regions.
# Count special (non-background) value in each region.
# If count is even -> output 1, if odd -> output background.

def transform(grid):
    # Find separator rows (all same value)
    sep_rows = []
    for r in range(len(grid)):
        if len(set(grid[r])) == 1:
            sep_rows.append(r)

    # Find separator columns (all same value)
    sep_cols = set()
    for c in range(len(grid[0])):
        if all(grid[r][c] == grid[0][c] for r in range(len(grid))):
            sep_cols.add(c)

    # Non-separator rows and columns
    row_set = set(range(len(grid)))
    col_set = set(range(len(grid[0])))

    non_sep_rows = [r for r in row_set if r not in sep_rows]
    non_sep_cols = [c for c in col_set if c not in sep_cols]

    # Determine bands (regions between separators)
    if sep_rows:
        bands = []
        prev = -3
        for sep in sep_rows:
            bands.append(range(prev + 4, sep))
            prev = sep
        bands.append(range(prev + 4, len(grid)))
    else:
        bands = [range(len(grid))]

    if sep_cols:
        bands_h = []
        prev = -3
        for sep in sorted(sep_cols):
            bands_h.append(range(prev + 4, sep))
            prev = sep
        bands_h.append(range(prev + 4, len(grid[0])))
    else:
        bands_h = [range(len(grid[0]))]

    num_output_rows = len(bands)
    num_output_cols = len(bands_h)

    # Determine background and special values
    counts = {}
    for r in non_sep_rows:
        for c in non_sep_cols:
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    sorted_vals = sorted(counts.items(), key=lambda x: -x[1])
    background = sorted_vals[0][0]
    special = sorted_vals[1][0] if len(sorted_vals) > 1 else sorted_vals[0][0]

    # Apply rule
    output = []
    for r_band, band in enumerate(bands):
        row = []
        for c_band, band_h in enumerate(bands_h):
            count = sum(1 for i in band for j in band_h if grid[i][j] == special)
            if count % 2 == 0:
                row.append(1)
            else:
                row.append(background)
        output.append(row)

    return output

